import {forestCover} from './scenery';
import {CHUNK_LENGTH,riverChannelAt} from './road';
import {CHUNK_RADIUS} from './window';
import {terrainRow} from './terrain-grid';
export interface HorizonData{center:number;positions:Float32Array;normals:Float32Array;colors:Float32Array;indices:Uint32Array[];}
/** Coarse bands stitch to the full world's exact outer rows. Same terrain/seed,
 * no new world or collision surface. Generated by the existing single worker. */
export function generateHorizon(center:number,seed:number):HorizonData{
  const positions:number[]=[],normals:number[]=[],colors:number[]=[],indices:number[][]=[[],[],[]];
  const origin=center*CHUNK_LENGTH;
  const color=(row:ReturnType<typeof terrainRow>,z:number)=>{
    const river=riverChannelAt(z,seed).x;
    return Array.from(row.x,(x,index)=>[forestCover(x,z,seed,row.y[index]),Math.exp(-Math.abs(x-river)/40),0]);
  };
  for(const side of [-1,1]){
    // An overlap greater than a full predictive-window reversal remains prepared.
    // The renderer clips it against the actual loaded window, preventing gaps.
    const start=origin+(side<0?-CHUNK_RADIUS:CHUNK_RADIUS+1)*CHUNK_LENGTH-side*1400,end=origin+side*5600;
    const samples=[start,start+side*20,start+side*100];
    for(let z=start+side*200;side*(end-z)>0;z+=side*200)samples.push(z);samples.push(end);
    if(side<0)samples.reverse();
    let a=terrainRow(samples[0],seed),ac=color(a,samples[0]);
    const base=positions.length/3,cells=a.x.length-1,rows=samples.length-1;
    const vertex=(r:number,c:number)=>base+(Math.min(r,rows-1)*cells+Math.min(c,cells-1))*6+(r===rows?(c===cells?5:1):c===cells?2:0);
    for(const [tier,stride] of [4,2,1].entries())for(let c=0;c<cells;c++)for(let row=0;row<rows;){const end=Math.min(rows,row+(Math.abs(samples[row]-origin)<4000?1:stride));indices[tier].push(vertex(row,c),vertex(end,c),vertex(row,c+1),vertex(row,c+1),vertex(end,c),vertex(end,c+1));row=end;}

    for(let row=0;row<samples.length-1;row++){
      const b=terrainRow(samples[row+1],seed),bc=color(b,samples[row+1]);
      for(let i=0;i<a.x.length-1;i++)for(const [r,index] of [[0,i],[1,i],[0,i+1],[0,i+1],[1,i],[1,i+1]]){
        const data=r?b:a,c=r?bc:ac,z=r?samples[row+1]:samples[row];
        positions.push(data.x[index],data.y[index],z-origin);normals.push(...data.normals.subarray(index*3,index*3+3));colors.push(...c[index]);
      }
      a=b;ac=bc;
    }
  }
  return {center,positions:new Float32Array(positions),normals:new Float32Array(normals),colors:new Float32Array(colors),indices:indices.map(values=>new Uint32Array(values))};
}
